function PublicCheckoutPage({ onBack, onContinue, onLogin }) {
  const [method, setMethod] = useState('CARTAO')
  const [card, setCard] = useState({ name: '', number: '', expiry: '', securityCode: '' })
  const [error, setError] = useState('')
  const cardNumber = card.number.replace(/\D/g, '')

  function updateCard(field, value) {
    if (field === 'number') value = (value.replace(/\D/g, '').slice(0, 16).match(/.{1,4}/g) || []).join(' ')
    if (field === 'expiry') value = value.replace(/\D/g, '').slice(0, 4).replace(/^(\d{2})(\d)/, '$1/$2')
    if (field === 'securityCode') value = value.replace(/\D/g, '').slice(0, 4)
    setCard((current) => ({ ...current, [field]: value }))
  }

  function continueToSignup(event) {
    event.preventDefault()
    setError('')
    if (method === 'CARTAO' && (!card.name.trim() || cardNumber.length !== 16 || !/^(0[1-9]|1[0-2])\/\d{2}$/.test(card.expiry) || card.securityCode.length < 3)) {
      setError('Preencha os campos do cartão de demonstração. Use somente dados fictícios.')
      return
    }
    setCard({ name: '', number: '', expiry: '', securityCode: '' })
    onContinue(method)
  }

  return <div className="public-plans-page">
    <header className="public-plans-header"><button className="public-plans-back" onClick={onBack}>← Voltar ao plano</button><img src={LOGO_URL} alt="Nexora" /><button className="public-plans-login" onClick={onLogin}>Já tenho conta</button></header>
    <main className="public-checkout-main"><div className="public-plans-intro"><span className="landing-section-kicker">FINALIZAÇÃO DO PLANO</span><h1>Escolha como deseja pagar.</h1><p>Nexora Pro · R$ 500,00 por mês</p></div>
      <form className="public-checkout-card" onSubmit={continueToSignup}>
        <div className="public-checkout-methods" role="radiogroup" aria-label="Forma de pagamento">
          {[['CARTAO', 'Cartão'], ['PIX', 'PIX'], ['BOLETO', 'Boleto']].map(([value, label]) => <label className={`public-method-option ${method === value ? 'selected' : ''}`} key={value}><input type="radio" name="payment-method" value={value} checked={method === value} onChange={() => { setMethod(value); setError('') }} /><span>{label}</span></label>)}
        </div>
        {method === 'CARTAO' && <div className="public-card-fields"><div className="public-card-fields-heading"><CreditCard size={19} /><div><strong>Dados do cartão de demonstração</strong><span>Use somente informações fictícias. Estes campos não são enviados nem salvos.</span></div></div><label>Nome no cartão<input autoComplete="off" value={card.name} onChange={(event) => updateCard('name', event.target.value)} placeholder="Ex.: Cartão de Teste" /></label><label>Número do cartão<input autoComplete="off" inputMode="numeric" value={card.number} onChange={(event) => updateCard('number', event.target.value)} placeholder="0000 0000 0000 0000" /></label><div className="public-card-fields-row"><label>Validade<input autoComplete="off" inputMode="numeric" value={card.expiry} onChange={(event) => updateCard('expiry', event.target.value)} placeholder="MM/AA" /></label><label>Código de segurança<input autoComplete="off" inputMode="numeric" value={card.securityCode} onChange={(event) => updateCard('securityCode', event.target.value)} placeholder="CVV" /></label></div></div>}
        {method === 'PIX' && <div className="public-checkout-info"><strong>PIX demonstrativo</strong><p>O pagamento será apenas simulado depois do cadastro. Nenhuma transferência ou cobrança será feita.</p></div>}
        {method === 'BOLETO' && <div className="public-checkout-info"><strong>Boleto demonstrativo</strong><p>Nenhum boleto real será emitido. A aprovação será simulada depois do cadastro.</p></div>}
        {error && <p className="public-checkout-error" role="alert">{error}</p>}
        <div className="public-checkout-total"><span>Total mensal</span><strong>R$ 500,00</strong></div>
        <button className="landing-primary public-checkout-submit" type="submit">Continuar para cadastro <ArrowRight size={17} /></button>
        <p className="public-checkout-disclaimer"><ShieldCheck size={15} />Simulador de desenvolvimento. Não digite dados reais. Nenhuma informação de cartão é enviada, armazenada ou cobrada.</p>
      </form>
    </main><footer className="public-plans-footer">© {new Date().getFullYear()} Nexora · Gestão conectada ao campo</footer>
  </div>
}

function GlobalPagination({ activeMenu }) { const keyByMenu = { Fornecedores: 'suppliers', Compras: 'purchases', Financeiro: 'finance', Equipamentos: 'equipment', 'Agenda de campo': 'agenda', Documentos: 'documents' }; const page = visualPageApi[keyByMenu[activeMenu]]; if (!page?.pagination?.totalPages || page.pagination.totalPages <= 1) return null; return <Pagination pagination={page.pagination} onPage={(nextPage) => page.onLoad({ page: nextPage })} /> }
function DataState({ message, action }) { return <div className="data-state panel"><p>{message}</p>{action}</div> }
function NexoraAIChat({ session, aiDraft, setAiDraft, aiMessages, setAiMessages, aiLoading, setAiLoading, aiError, setAiError }) {
  const [puterConnected, setPuterConnected] = useState(false)

  useEffect(() => {
    let mounted = true
    Promise.resolve(puter.auth.isSignedIn()).then((signedIn) => { if (mounted) setPuterConnected(Boolean(signedIn)) }).catch(() => { if (mounted) setPuterConnected(false) })
    return () => { mounted = false }
  }, [])

  async function connectPuter() {
    setAiError('')
    try {
      await puter.auth.signIn()
      setPuterConnected(true)
    } catch (error) {
      setAiError(error.message || 'Não foi possível autenticar o Puter.')
    }
  }

  async function submitQuestion(event) {
    event.preventDefault();
    const trimmed = aiDraft.trim();
    if (!trimmed || aiLoading) return;
    setAiLoading(true); setAiError('');
    const nextMessages = [...aiMessages, { role: 'user', content: trimmed }];
    setAiMessages(nextMessages);
    setAiDraft('');

    try {
      const response = await fetch(`${API_URL}/ai/chat`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${session.token}`,
        },
        body: JSON.stringify({ message: trimmed }),
      });
      const payload = await response.json();
      if (!response.ok) {
        throw new Error(payload?.error || 'Não foi possível consultar o Nexora AI agora.')
      }
      let answer = payload.answer
      if (payload.provider === 'puter') {
        if (!puterConnected) throw new Error('Conecte sua conta Puter antes de consultar o Nexora AI.')
        const completion = await puter.ai.chat([
          { role: 'system', content: payload.prompt },
          { role: 'user', content: JSON.stringify({ question: trimmed, context: payload.context }) },
        ], { model: 'openai/gpt-5.5', temperature: 0.1, max_tokens: 300, normalize: true })
        const content = completion?.message?.content ?? completion?.content ?? completion?.text
        answer = Array.isArray(content) ? content.map((part) => part?.text || '').join('') : content
      }
      setAiMessages([...nextMessages, { role: 'assistant', content: answer || 'Não encontrei informação suficiente para responder.' }]);
    } catch (error) {
      setAiError(error.message || 'Não foi possível consultar o Nexora AI agora.')
      setAiMessages([...nextMessages, { role: 'assistant', content: error.message || 'Não foi possível consultar o Nexora AI agora.' }]);
    } finally {
      setAiLoading(false)
    }
  }

  return <><SectionHeading kicker="ASSISTENTE INTEGRADO" title="Nexora AI" description="Consultas seguras e somente leitura para sua operação." action={<div className="ai-heading-actions"><button className="outline-button" onClick={connectPuter} disabled={puterConnected}>{puterConnected ? 'Puter conectado' : 'Conectar Puter'}</button><button className="outline-button" onClick={() => { setAiMessages([]); setAiError(''); setAiDraft('') }}>Limpar conversa</button></div>} /><div className="panel ai-chat-panel"><div className="ai-chat-thread">{!aiMessages.length && <div className="ai-empty-state"><Bot size={28} /><p>Olá! Posso responder sobre financeiro, estoque, projetos, compras e agenda com base nos dados da sua empresa.</p></div>}{aiMessages.map((message, index) => <div key={`${message.role}-${index}`} className={`ai-message ${message.role}`}><strong>{message.role === 'user' ? 'Você' : 'Assistente'}</strong><p>{message.content}</p></div>)}{aiLoading && <div className="ai-message assistant"><strong>Assistente</strong><p>Consultando o contexto da empresa...</p></div>}</div>{aiError && <div className="form-error">{aiError}</div>}<form className="ai-chat-form" onSubmit={submitQuestion}><textarea value={aiDraft} onChange={(event) => setAiDraft(event.target.value)} placeholder="Pergunte sobre seu negócio..." rows={3} maxLength={500} /><div className="ai-chat-actions"><span>{aiDraft.length}/500</span><button className="blue-button" type="submit" disabled={aiLoading || !aiDraft.trim()}>{aiLoading ? 'Consultando...' : 'Enviar'}</button></div></form></div></>
}
function AuthScreen({ view, setView, error, info, onLogin, onSignup }) {
  const login = view === 'login'
  const [signupMode, setSignupMode] = useState('create')
const { formRef, lookupState, onBlurCapture, lookupCurrentCnpj } = useBusinessAutofill()
  return <div className="auth-shell"><div className="auth-visual"><img src={LOGO_URL} alt="Nexora" /><div className="visual-message"><span>GESTÃO QUE ACOMPANHA O CAMPO</span><h1>Mais controle.<br /><em>Mais colheita.</em></h1><p>Organize projetos, equipes e equipamentos em um só lugar.</p></div><div className="visual-footer"><span>nexora.app</span><span>Feito para quem constrói o agro.</span></div></div><div className="auth-panel"><div className="auth-mobile-brand"><img src={LOGO_URL} alt="Nexora" /></div><div className="auth-form-wrap"><div className="auth-kicker">{login ? 'BEM-VINDO DE VOLTA' : 'COMECE SUA JORNADA'}</div><h2>{login ? 'Acesse sua operação' : signupMode === 'create' ? 'Cadastre sua empresa' : 'Peça acesso à empresa'}</h2><p className="auth-intro">{login ? 'Entre para acompanhar suas obras em tempo real.' : signupMode === 'create' ? 'A primeira pessoa cadastrada será administradora da empresa.' : 'Seu pedido será analisado por um administrador da empresa.'}</p>{error && <div className="form-error">{error}</div>}{info && <div className="auth-success-message" role="status">{info}</div>}{login ? <form onSubmit={onLogin}><Field label="E-mail corporativo" name="email" type="email" placeholder="voce@empresa.com" /><Field label="Senha" name="password" type="password" placeholder="••••••••" /><div className="form-row"><label className="check-label"><input type="checkbox" /> Lembrar de mim</label><button type="button" className="link-button">Esqueci minha senha</button></div><button className="auth-button">Entrar no Nexora <ArrowRight size={17} /></button></form> : <><div className="auth-signup-modes"><button type="button" className={signupMode === 'create' ? 'active' : ''} onClick={() => { setSignupMode('create'); }} >Criar empresa</button><button type="button" className={signupMode === 'join' ? 'active' : ''} onClick={() => { setSignupMode('join'); }} >Solicitar acesso</button></div><form ref={formRef} onBlurCapture={onBlurCapture} onSubmit={onSignup}><input type="hidden" name="registrationType" value={signupMode === 'join' ? 'join' : 'create'} />{signupMode === 'create' ? <><div className="auth-form-section"><strong>Dados da empresa</strong><span>Identificação e endereço comercial</span></div><div className="form-grid"><Field label="Razão social" name="legal_name" placeholder="Ex.: Horizonte Armazenagem Ltda." /></div><div className="form-grid"><Field label="Nome fantasia" name="trade_name" placeholder="Ex.: Fazenda Horizonte" /><Field label="CNPJ" name="cnpj" placeholder="00.000.000/0000-00" inputMode="text" autoCapitalize="characters" maxLength={18} /><button type="button" className="lookup-button" disabled={lookupState.busy} onClick={lookupCurrentCnpj}>{lookupState.busy ? "Consultando…" : "Buscar dados"}</button></div>{lookupState.message && <p className={lookupState.error ? "lookup-message error" : "lookup-message"} role="status">{lookupState.message}</p>}<div className="form-grid"><Field label="E-mail comercial (opcional)" name="company_email" type="email" placeholder="contato@empresa.com.br" required={false} /><Field label="Telefone comercial (opcional)" name="company_phone" type="tel" placeholder="(00) 00000-0000" required={false} /></div><div className="form-grid"><Field label="Atividade principal (opcional)" name="segment" placeholder="Preenchida pela consulta do CNPJ" required={false} /><Field label="Site da empresa (opcional)" name="website" type="url" placeholder="https://empresa.com.br" required={false} /></div><div className="form-grid"><Field label="CEP (opcional)" name="zip_code" placeholder="00000-000" inputMode="numeric" maxLength={9} required={false} /><Field label="Endereço (opcional)" name="address" placeholder="Rua ou avenida" required={false} /></div><div className="form-grid"><Field label="Número (opcional)" name="address_number" placeholder="Nº" required={false} /><Field label="Complemento (opcional)" name="complement" placeholder="Sala, bloco..." required={false} /></div><div className="form-grid"><Field label="Bairro (opcional)" name="district" placeholder="Bairro" required={false} /><Field label="Município (opcional)" name="city" placeholder="Cidade" required={false} /></div><Field label="UF (opcional)" name="state" placeholder="GO" maxLength={2} required={false} /><div className="auth-form-section"><strong>Administrador da empresa</strong><span>Esta primeira conta terá controle administrativo</span></div><div className="form-grid"><Field label="Nome completo" name="userName" placeholder="Seu nome" /><Field label="E-mail de acesso" name="email" type="email" placeholder="voce@empresa.com.br" /></div><Field label="Senha (mínimo de 12 caracteres)" name="password" type="password" placeholder="Crie uma senha segura" minLength={12} maxLength={72} /></> : <><div className="auth-form-section"><strong>Dados para localizar a empresa</strong><span>A empresa precisa já estar cadastrada no Nexora</span></div><Field label="CNPJ da empresa" name="cnpj" placeholder="00.000.000/0000-00" inputMode="text" autoCapitalize="characters" maxLength={18} /><div className="auth-form-section"><strong>Seus dados</strong><span>A empresa verá essas informações ao analisar o pedido</span></div><div className="form-grid"><Field label="Nome completo" name="userName" placeholder="Seu nome" /><Field label="E-mail de acesso" name="email" type="email" placeholder="voce@empresa.com.br" /></div><div className="form-grid"><Field label="Telefone (opcional)" name="phone" type="tel" placeholder="(00) 00000-0000" required={false} /><Field label="Cargo / função (opcional)" name="job_title" placeholder="Ex.: Comprador" required={false} /></div><Field label="Setor (opcional)" name="department" placeholder="Ex.: Suprimentos" required={false} /><Field label="Crie uma senha (mínimo de 12 caracteres)" name="password" type="password" placeholder="Após a aprovação, use esta senha para entrar" minLength={12} maxLength={72} /></>}<button className="auth-button">{signupMode === 'create' ? 'Criar empresa e continuar' : 'Enviar pedido de acesso'} <ArrowRight size={17} /></button></form></>}<p className="auth-switch">{login ? 'Ainda não tem uma conta?' : 'Já possui uma conta?'} <button className="link-button" onClick={() => setView(login ? 'signup' : 'login')}>{login ? 'Cadastre sua empresa ou solicite acesso' : 'Entrar agora'}</button></p></div></div></div>
}

function Field({ label, ...props }) { return <label className="field"><span>{label}</span><input required {...props} /></label> }
function SectionHeading({ kicker, title, description, action }) { return <section className="section-heading"><div><span className="section-kicker">{kicker}</span><h1>{title}</h1><p>{description}</p></div>{action}</section> }
function Overview({ projects, liveStats, onNavigate }) { const dashboard = liveStats || {}; const stats = dashboard.stats || []; const iconMap = { Factory, Truck, Warehouse, ClipboardList, Wrench }; const operational = dashboard.operational || {}; const financial = dashboard.financial; return <><SectionHeading kicker="DADOS DA OPERAÇÃO" title="Visão geral" description="Indicadores carregados da empresa autenticada." /><div className="metric-grid">{stats.map((stat) => <Metric key={stat.label} icon={iconMap[stat.icon] || ClipboardList} label={stat.label} value={stat.value} detail={stat.detail} color={stat.tone === 'purple' ? 'sky' : stat.tone} />)}</div>{financial && <div className="metric-grid three"><Metric icon={WalletCards} label="A pagar" value={`R$ ${financial.payable.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`} detail="Contas pendentes" color="amber" /><Metric icon={ReceiptText} label="A receber" value={`R$ ${financial.receivable.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`} detail="Receitas pendentes" color="blue" /><Metric icon={BarChart3} label="Saldo previsto" value={`R$ ${financial.projectedBalance.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}`} detail="Receber menos pagar" color="green" /></div>}{!stats.length && <DataState message="Não há indicadores cadastrados." />}<div className="dashboard-grid"><div className="panel"><PanelHeading title="Projetos em andamento" subtitle="Dados reais da API" action={<button className="quiet-button" onClick={() => onNavigate('Projetos e obras')}>Ver todos <ArrowRight size={14} /></button>} /><ProjectTable projects={projects} /></div><div className="panel agenda-card"><PanelHeading title="Agenda de campo" subtitle={`${operational.upcomingActivities?.length || 0} próximas atividades`} action={<button className="circle-button" onClick={() => onNavigate('Agenda de campo')}><Plus size={16} /></button>} />{operational.upcomingActivities?.length ? operational.upcomingActivities.map((activity) => <AgendaItem key={activity.id} time={activity.starts_at} title={activity.title} company={activity.type || 'Atividade'} color="blue" />) : <DataState message="Não há atividades próximas." />}</div></div><div className="dashboard-grid lower"><div className="panel"><PanelHeading title="Alertas operacionais" subtitle="Somente dados reais" />{operational.overdueProjects || operational.pendingTasks || operational.criticalStock?.length ? <div className="module-list"><div className="module-row"><div><b>Projetos atrasados</b><small>{operational.overdueProjects || 0} projeto(s)</small></div></div><div className="module-row"><div><b>Tarefas pendentes</b><small>{operational.pendingTasks || 0} tarefa(s)</small></div></div><div className="module-row"><div><b>Estoque crítico</b><small>{operational.criticalStock?.length || 0} item(ns)</small></div></div></div> : <DataState message="Nenhum alerta operacional." />}</div><div className="panel"><PanelHeading title="Pendências recentes" subtitle="Compras e manutenção" />{operational.pendingPurchases?.length || operational.upcomingMaintenance?.length ? <div className="module-list">{(operational.pendingPurchases || []).slice(0, 3).map((item) => <div className="module-row" key={`purchase-${item.id}`}><div><b>{item.justification || 'Compra pendente'}</b><small>Compra · {item.status}</small></div></div>)}{(operational.upcomingMaintenance || []).slice(0, 3).map((item) => <div className="module-row" key={`maintenance-${item.id}`}><div><b>{item.equipment_name}</b><small>Manutenção · {item.scheduled_at || item.status}</small></div></div>)}</div> : <DataState message="Nenhuma pendência recente." />}</div></div></> }
function Metric({ icon, label, value, detail, color }) { const Icon = typeof icon === 'string' ? iconComponents[icon] || ClipboardList : icon || ClipboardList; return <article className="metric"><div className={`metric-icon ${color}`}><Icon size={18} /></div><span>{label}</span><strong>{value}</strong><small>{detail}</small></article> }
function PanelHeading({ title, subtitle, action }) { return <div className="panel-heading"><div><h2>{title}</h2><p>{subtitle}</p></div>{action}</div> }
function ProjectTable({ projects, onEdit }) { return <div className="table-scroll"><table><thead><tr><th>OBRA / CONTRATANTE</th><th>PROGRESSO</th><th>STATUS</th><th>ENTREGA</th>{onEdit && <th />}</tr></thead><tbody>{projects.map((project) => <tr key={project.code}><td><div className="project-name"><span className={`project-icon ${project.tone}`}><Factory size={15} /></span><span><b>{project.name}</b><small>{project.code} · {project.location}</small></span></div></td><td><div className="progress"><span><i style={{ width: `${project.progress}%` }} /></span>{project.progress}%</div></td><td><em className={`status ${project.tone}`}>{project.status}</em></td><td>{project.due}</td>{onEdit && <td><button className="table-action" onClick={() => onEdit(project)}>Editar</button></td>}</tr>)}</tbody></table>{!projects.length && <div className="empty">Nenhum projeto encontrado.</div>}</div> }
function AgendaItem({ time, title, company, color }) { return <div className="agenda-item"><time>{time}</time><div><b>{title}</b><small>{company}</small></div><i className={color} /></div> }
function StockPage({ supplies, projects, pagination, onLoad, onNew, onNewRequest, notify }) { pagination ||= visualPageApi.stock.pagination; onLoad ||= visualPageApi.stock.onLoad; const [search, setSearch] = useState(''); function filter(event) { event.preventDefault(); onLoad({ search, page: 1 }) } return <><SectionHeading kicker="CONTROLE DE MATERIAIS" title="Estoque" description="Visibilidade do que está disponível e do que precisa ser reposto." action={<div className="row-actions"><button className="outline-button" onClick={onNewRequest}><Plus size={16} /> Nova solicitação</button><button className="blue-button" onClick={onNew}><Plus size={17} /> Novo registro</button></div>} /><div className="metric-grid three"><Metric icon={Package} label="Itens cadastrados" value={String(pagination?.total || supplies.length)} detail="Saldo vindo da API" color="blue" /><Metric icon={Warehouse} label="Reservas" value="-" detail="Consulte movimentações" color="sky" /><Metric icon={Bell} label="Alertas" value="-" detail="Sem indicador disponível" color="amber" /></div><form className="filter-bar panel" onSubmit={filter}><label className="search-box"><Search size={15} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar por produto ou SKU" /></label><button className="outline-button">Filtrar</button></form><div className="page-panel panel inventory"><PanelHeading title="Visão do estoque" subtitle="Posição atual por item e obra de destino" action={<button className="outline-button" onClick={() => notify('Relatório de estoque ainda não está conectado.')}>Exportar relatório</button>} /><table><thead><tr><th>INSUMO</th><th>CATEGORIA</th><th>OBRA DE DESTINO</th><th>DISPONÍVEL</th><th>SITUAÇÃO</th></tr></thead><tbody>{supplies.map((item, index) => <tr key={`${item.name}-${index}`}><td><b>{item.name}</b></td><td>{item.category}</td><td>{projects.find((project) => project.id === item.project_id)?.name || 'Estoque central'}</td><td>{item.amount}</td><td><em className={`status ${item.tone}`}>{item.status}</em></td></tr>)}</tbody></table>{!supplies.length && <div className="empty">Não há dados cadastrados.</div>}<Pagination pagination={pagination} onPage={(page) => onLoad({ search, page })} /></div></> }
function AgendaPage({ activities, onCreate, onEdit, onDelete, notify }) { const [modal, setModal] = useState(null); return <><SectionHeading kicker="PLANEJAMENTO DE CAMPO" title="Agenda de campo" description="Coordene visitas, medições e inspeções da sua equipe." action={<button className="blue-button" onClick={() => setModal({})}><Plus size={17} /> Nova atividade</button>} /><div className="calendar-layout"><div className="panel calendar-panel"><div className="calendar-header"><button onClick={() => notify('Mês anterior')}>‹</button><strong>Setembro 2026</strong><button onClick={() => notify('Próximo mês')}>›</button></div><div className="weekdays">{['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'].map((day) => <span key={day}>{day}</span>)}</div><div className="calendar-days">{Array.from({ length: 30 }, (_, index) => <button className={index + 1 === 21 ? 'today' : ''} key={index}>{index + 1}</button>)}</div></div><div className="panel day-agenda"><PanelHeading title="Atividades agendadas" subtitle={`${activities.length} eventos persistidos`} />{activities.map((activity, index) => <div className="agenda-record" key={activity.id}><AgendaItem time={activity.starts_at || '--:--'} title={activity.title} company={activity.type || 'Atividade de campo'} color={['blue', 'amber', 'green'][index % 3]} /><div className="row-actions"><button className="table-action" onClick={() => setModal(activity)}>Editar</button><button className="table-action danger" onClick={() => onDelete(activity)}>Excluir</button></div></div>)}{!activities.length && <div className="empty">Nenhuma atividade cadastrada.</div>}</div></div>{modal && <ActivityModal activity={modal.id ? modal : null} onClose={() => setModal(null)} onCreate={(data) => { if (modal.id) onEdit(modal, data); else onCreate(data); setModal(null) }} />}</> }
function ActivityModal({ activity, onClose, onCreate }) { const value = (field) => activity?.[field] || ''; return <div className="modal-layer" onClick={onClose}><form className="modal-card" onClick={(event) => event.stopPropagation()} onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onCreate(Object.fromEntries(form.entries())) }}><button type="button" className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">AGENDA DE CAMPO</span><h2>{activity ? 'Editar atividade' : 'Nova atividade'}</h2><p>Crie um evento persistente para sua equipe.</p><Field label="Título" name="title" defaultValue={value('title')} placeholder="Visita técnica" /><div className="form-grid"><label className="field"><span>Tipo</span><select name="type" defaultValue={value('type') || 'Visita técnica'}><option>Visita técnica</option><option>Reunião</option><option>Inspeção</option><option>Entrega</option><option>Instalação</option><option>Manutenção</option><option>Vistoria</option></select></label><Field label="Data e hora inicial" name="starts_at" type="datetime-local" defaultValue={value('starts_at')} /></div><div className="form-grid"><Field label="Responsável" name="responsible" defaultValue={value('responsible')} placeholder="Responsável" /><Field label="Local" name="location" defaultValue={value('location')} placeholder="Local do evento" /></div><label className="field"><span>Descrição</span><textarea name="description" defaultValue={value('description')} placeholder="Detalhes da atividade" /></label><div className="modal-actions"><button type="button" className="outline-button" onClick={onClose}>Cancelar</button><button className="blue-button">Salvar atividade</button></div></form></div> }
function EquipmentPage({ equipments, maintenances, onCreate, onEdit, onDelete, onMaintenanceCreate, onMaintenanceEdit, onMaintenanceDelete }) { const [modal, setModal] = useState(null); const [maintenanceModal, setMaintenanceModal] = useState(null); return <><SectionHeading kicker="ATIVOS E MÁQUINAS" title="Equipamentos" description="Controle máquinas, localização, responsáveis e manutenção." action={<button className="blue-button" onClick={() => setModal({})}><Plus size={17} /> Novo equipamento</button>} /><div className="metric-grid three"><Metric icon={Wrench} label="Equipamentos cadastrados" value={String(equipments.length)} detail="Dados reais da empresa" color="blue" /><Metric icon={CalendarDays} label="Manutenções em aberto" value={String(maintenances.filter((item) => item.status !== 'CONCLUIDA' && item.status !== 'CANCELADA').length)} detail="Acompanhe os prazos" color="amber" /><Metric icon={Factory} label="Em operação" value={String(equipments.filter((item) => item.status !== 'INATIVO').length)} detail="Disponíveis ou em campo" color="green" /></div><div className="page-panel panel"><PanelHeading title="Frota e equipamentos" subtitle="Ativos persistidos no banco" action={<button className="outline-button" onClick={() => setMaintenanceModal({})}>Nova manutenção</button>} /><div className="table-scroll"><table><thead><tr><th>CÓDIGO</th><th>EQUIPAMENTO</th><th>TIPO</th><th>PROJETO</th><th>STATUS</th><th /></tr></thead><tbody>{equipments.map((equipment) => <tr key={equipment.id}><td><b>{equipment.code}</b></td><td>{equipment.name}<small>{equipment.brand || 'Marca não informada'} {equipment.model || ''}</small></td><td>{equipment.type || '-'}</td><td>{equipment.project_id || 'Não alocado'}</td><td><em className="status green">{equipment.status}</em></td><td><div className="row-actions"><button className="table-action" onClick={() => setModal(equipment)}>Editar</button><button className="table-action danger" onClick={() => onDelete(equipment)}>Excluir</button></div></td></tr>)}</tbody></table>{!equipments.length && <div className="empty">Nenhum equipamento cadastrado.</div>}</div></div><div className="page-panel panel maintenance-panel"><PanelHeading title="Histórico de manutenção" subtitle={`${maintenances.length} registros persistidos`} />{maintenances.map((maintenance) => <div className="module-row" key={maintenance.id}><span className="module-row-icon amber"><Wrench size={16} /></span><div><b>{maintenance.equipment_name || maintenance.equipment_id}</b><small>{maintenance.type} · {maintenance.description}</small></div><em className={`status ${maintenance.status === 'CONCLUIDA' ? 'green' : 'amber'}`}>{maintenance.status}</em><button className="table-action" onClick={() => setMaintenanceModal(maintenance)}>Editar</button><button className="table-action danger" onClick={() => onMaintenanceDelete(maintenance)}>Cancelar</button></div>)}{!maintenances.length && <div className="empty">Nenhuma manutenção cadastrada.</div>}</div>{modal && <EquipmentModal equipment={modal.id ? modal : null} onClose={() => setModal(null)} onCreate={(data) => { if (modal.id) onEdit(modal, data); else onCreate(data); setModal(null) }} />}{maintenanceModal && <MaintenanceModal maintenance={maintenanceModal.id ? maintenanceModal : null} equipments={equipments} onClose={() => setMaintenanceModal(null)} onCreate={(data) => { if (maintenanceModal.id) onMaintenanceEdit(maintenanceModal, data); else onMaintenanceCreate(data); setMaintenanceModal(null) }} />}</> }
function EquipmentModal({ equipment, onClose, onCreate }) { const value = (field) => equipment?.[field] || ''; return <div className="modal-layer" onClick={onClose}><form className="modal-card supplier-modal" onClick={(event) => event.stopPropagation()} onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onCreate(Object.fromEntries(form.entries())) }}><button type="button" className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">{equipment ? 'EDITAR EQUIPAMENTO' : 'NOVO EQUIPAMENTO'}</span><h2>{equipment ? 'Atualize a máquina' : 'Cadastre uma máquina'}</h2><p>Registre o ativo para acompanhar operação e manutenção.</p><div className="form-grid"><Field label="Código" name="code" defaultValue={value('code')} placeholder="EQ-001" /><Field label="Nome" name="name" defaultValue={value('name')} placeholder="Máquina de solda" /></div><div className="form-grid"><Field label="Tipo" name="type" defaultValue={value('type')} placeholder="Solda / transporte" /><Field label="Marca" name="brand" defaultValue={value('brand')} placeholder="Marca" /></div><div className="form-grid"><Field label="Modelo" name="model" defaultValue={value('model')} placeholder="Modelo" /><Field label="Número de série" name="serial_number" defaultValue={value('serial_number')} placeholder="Número de série" /></div><div className="form-grid"><Field label="Ano" name="year" type="number" defaultValue={value('year')} /><Field label="Valor" name="value" type="number" step="0.01" defaultValue={value('value')} /></div><div className="form-grid"><Field label="Localização" name="location" defaultValue={value('location')} placeholder="Almoxarifado" /><Field label="Responsável" name="responsible" defaultValue={value('responsible')} placeholder="Responsável" /></div><label className="field"><span>Observações</span><textarea name="notes" defaultValue={value('notes')} /></label><div className="modal-actions"><button type="button" className="outline-button" onClick={onClose}>Cancelar</button><button className="blue-button">Salvar equipamento</button></div></form></div> }
function MaintenanceModal({ maintenance, equipments, onClose, onCreate }) { const value = (field) => maintenance?.[field] || ''; return <div className="modal-layer" onClick={onClose}><form className="modal-card" onClick={(event) => event.stopPropagation()} onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onCreate(Object.fromEntries(form.entries())) }}><button type="button" className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">MANUTENÇÃO</span><h2>{maintenance ? 'Editar manutenção' : 'Nova manutenção'}</h2><p>Registre o serviço e mantenha o histórico do equipamento.</p><label className="field"><span>Equipamento</span><select name="equipment_id" defaultValue={value('equipment_id')} required><option value="">Selecione</option>{equipments.map((equipment) => <option key={equipment.id} value={equipment.id}>{equipment.code} · {equipment.name}</option>)}</select></label><div className="form-grid"><label className="field"><span>Tipo</span><select name="type" defaultValue={value('type') || 'PREVENTIVA'}><option>PREVENTIVA</option><option>CORRETIVA</option><option>INSPEÇÃO</option></select></label><label className="field"><span>Status</span><select name="status" defaultValue={value('status') || 'AGENDADA'}><option>AGENDADA</option><option>EM_ANDAMENTO</option><option>CONCLUIDA</option><option>CANCELADA</option></select></label></div><div className="form-grid"><Field label="Data prevista" name="scheduled_at" type="date" defaultValue={value('scheduled_at')} /><Field label="Próxima manutenção" name="next_due_at" type="date" defaultValue={value('next_due_at')} /></div><div className="form-grid"><Field label="Responsável" name="responsible" defaultValue={value('responsible')} /><Field label="Fornecedor / oficina" name="supplier" defaultValue={value('supplier')} /></div><div className="form-grid"><Field label="Custo" name="cost" type="number" step="0.01" defaultValue={value('cost')} /><Field label="Horímetro" name="horometer" type="number" step="0.1" defaultValue={value('horometer')} /></div><Field label="Descrição" name="description" defaultValue={value('description')} placeholder="Serviço realizado ou previsto" /><label className="field"><span>Observações</span><textarea name="observations" defaultValue={value('observations')} /></label><div className="modal-actions"><button type="button" className="outline-button" onClick={onClose}>Cancelar</button><button className="blue-button">Salvar manutenção</button></div></form></div> }
function DocumentsPage({ scope, session, documents, onUpload, onDownload, onArchive, onDelete, onRename, notify }) {
  const [search, setSearch] = useState('')
  const [category, setCategory] = useState('')
  const [folders, setFolders] = useState([])
  const [folderId, setFolderId] = useState('')
  const [folderModal, setFolderModal] = useState(false)
  const [selectedFile, setSelectedFile] = useState('')
  const isContracts = scope === 'contracts'
  useEffect(() => { fetch(`${API_URL}/document-folders?scope=${scope}`, { headers: { Authorization: `Bearer ${session.token}` } }).then((response) => response.ok ? response.json() : []).then(setFolders).catch(() => setFolders([])); setFolderId('') }, [scope, session.token])
  const filtered = documents.filter((item) => `${item.name} ${item.category || ''}`.toLowerCase().includes(search.toLowerCase()) && (!category || item.category === category) && (!folderId || item.folder_id === folderId))
  function upload(event) {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const file = form.get('file')
    if (!file?.name) return notify('Selecione um arquivo.')
    if (isContracts && !file.name.toLowerCase().endsWith('.pdf')) return notify('Anexe o contrato em PDF.')
    form.set('scope', scope)
    if (folderId) form.set('folder_id', folderId)
    onUpload(form)
    event.currentTarget.reset()
    setSelectedFile('')
  }
  async function saveFolder(event) {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const name = String(form.get('name') || '').trim()
    if (!name) return
    const response = await fetch(`${API_URL}/document-folders`, { method: 'POST', headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${session.token}` }, body: JSON.stringify({ name, scope, parent_id: folderId || null }) })
    if (!response.ok) return notify('Não foi possível criar a pasta.')
    const folder = await response.json()
    setFolders((current) => [...current, folder])
    setFolderId(folder.id)
    setFolderModal(false)
    notify('Pasta criada dentro do Nexora.')
  }
  return <>
    <SectionHeading kicker={isContracts ? 'GESTÃO COMERCIAL' : 'CENTRAL DE DOCUMENTOS'} title={isContracts ? 'Contratos' : 'Documentos da empresa'} description={isContracts ? 'Organize e anexe contratos em PDF em pastas.' : 'Documentos institucionais da empresa, como cartão CNPJ e certidões.'} action={<button type="button" className="outline-button" onClick={() => setFolderModal(true)}><FolderPlus size={16} /> Nova pasta</button>} />
    <form className="document-upload-panel panel" onSubmit={upload}>
      <div className="document-upload-intro"><span className="document-icon"><FileText size={20} /></span><div><strong>{isContracts ? 'Anexar contrato' : 'Anexar documento da empresa'}</strong><small>{isContracts ? 'Envie arquivos PDF e escolha a pasta de destino.' : 'PDF, imagens e documentos da empresa em um só lugar.'}</small></div></div>
      <div className="document-upload-fields"><label className="document-file-select"><input name="file" type="file" accept={isContracts ? '.pdf,application/pdf' : '.pdf,.png,.jpg,.jpeg,.xlsx,.docx'} onChange={(event) => setSelectedFile(event.target.files?.[0]?.name || '')} /><span>Selecionar arquivo</span><small>{selectedFile || 'Nenhum arquivo selecionado'}</small></label><label className="field"><span>{isContracts ? 'Descrição (opcional)' : 'Categoria (opcional)'}</span><input name="category" placeholder={isContracts ? 'Ex.: Contrato de prestação' : 'Ex.: Certidões'} /></label><button className="blue-button"><Plus size={17} /> Anexar</button></div>
      {folderId && <div className="document-upload-destination">Salvando em: <b>{folders.find((folder) => folder.id === folderId)?.name || 'Pasta selecionada'}</b></div>}
    </form>
    <div className="filter-bar panel"><label className="search-box"><Search size={15} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={isContracts ? 'Buscar contrato' : 'Buscar documento'} /></label><select className="filter-input" value={folderId} onChange={(event) => setFolderId(event.target.value)}><option value="">Todas as pastas</option>{folders.map((folder) => <option key={folder.id} value={folder.id}>{folder.name}</option>)}</select>{!isContracts && <select className="filter-input" value={category} onChange={(event) => setCategory(event.target.value)}><option value="">Todas as categorias</option><option>Documentos da empresa</option><option>Certidões</option><option>Comprovantes</option><option>Certificados</option></select>}</div>
    <div className="document-folder-grid">{folders.map((folder) => <button type="button" key={folder.id} className={`document-folder-card ${folderId === folder.id ? 'selected' : ''}`} onClick={() => setFolderId(folderId === folder.id ? '' : folder.id)}><FolderPlus size={18} /><span>{folder.name}</span><small>{documents.filter((item) => item.folder_id === folder.id).length} arquivo(s)</small></button>)}</div>
    <div className="document-grid">{filtered.map((item) => <article className="document-card" key={item.id}><div className="document-icon"><FileText size={21} /></div><div><h3>{item.name}</h3><p>{item.category || (isContracts ? 'Contrato PDF' : 'Documento da empresa')} · {Math.ceil((item.size || 0) / 1024)} KB</p></div><div className="document-actions"><button onClick={() => onDownload(item)}>Baixar</button><button onClick={() => onRename(item, window.prompt('Novo nome', item.name) || item.name)}>Renomear</button><button onClick={() => onArchive(item)}>Arquivar</button><button onClick={() => onDelete(item)}>Excluir</button></div></article>)}{!filtered.length && <div className="empty panel">{isContracts ? 'Nenhum contrato encontrado.' : 'Nenhum documento encontrado.'}</div>}</div>
    {folderModal && <div className="modal-layer" onClick={() => setFolderModal(false)}><form className="modal-card employee-small-modal" onClick={(event) => event.stopPropagation()} onSubmit={saveFolder}><button type="button" className="modal-x" onClick={() => setFolderModal(false)}><X size={18} /></button><span className="section-kicker">ORGANIZAÇÃO DE ARQUIVOS</span><h2>Nova pasta</h2><p>{folderId ? `A pasta será criada dentro de “${folders.find((folder) => folder.id === folderId)?.name || 'pasta selecionada'}”.` : 'Crie uma pasta para organizar seus arquivos.'}</p><label className="field"><span>Nome da pasta</span><input name="name" maxLength={120} autoFocus required placeholder="Ex.: Certidões" /></label><div className="modal-actions"><button type="button" className="outline-button" onClick={() => setFolderModal(false)}>Cancelar</button><button className="blue-button">Criar pasta</button></div></form></div>}
  </>
}
function ClientsPage({ clients, pagination, onLoad, onSave, onArchive, can }) { pagination ||= visualPageApi.clients.pagination; onLoad ||= visualPageApi.clients.onLoad; const [search, setSearch] = useState(''); const [city, setCity] = useState(''); const [modal, setModal] = useState(null); function filter(event) { event.preventDefault(); onLoad({ search, city, page: 1 }) } return <><SectionHeading kicker="RELACIONAMENTO" title="Clientes" description="Empresas e pessoas que fazem parte da sua operação." action={can('clients', 'create') && <button className="blue-button" onClick={() => setModal({})}><Plus size={17} /> Novo cliente</button>} /><form className="filter-bar panel" onSubmit={filter}><label className="search-box"><Search size={15} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar cliente ou documento" /></label><input className="filter-input" value={city} onChange={(event) => setCity(event.target.value)} placeholder="Cidade" /><button className="outline-button">Filtrar</button></form><div className="client-grid">{clients.map((client) => <article className="client-card" key={client.id}><div className="client-logo">{(client.trade_name || client.legal_name).split(' ').map((word) => word[0]).join('').slice(0, 2)}</div><h3>{client.trade_name || client.legal_name}</h3><p>{client.city || 'Cidade não informada'}{client.state ? ` / ${client.state}` : ''}</p><small>{client.document || 'Documento não informado'}</small><div className="row-actions">{can('clients', 'edit') && <button className="table-action" onClick={() => setModal(client)}>Editar</button>}{can('clients', 'archive') && <button className="table-action danger" onClick={() => onArchive(client)}>Arquivar</button>}</div></article>)}{!clients.length && <div className="empty panel">Não há dados cadastrados.</div>}</div><Pagination pagination={pagination} onPage={(page) => onLoad({ search, city, page })} />{modal && <ClientModal client={modal.id ? modal : null} onClose={() => setModal(null)} onSave={(data) => { onSave(data, modal.id); setModal(null) }} />}</> }
function ClientModal({ client, onClose, onSave }) { const value = (field) => client?.[field] || ''; return <div className="modal-layer" onClick={onClose}><form className="modal-card" onClick={(event) => event.stopPropagation()} onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onSave(Object.fromEntries(form.entries())) }}><button type="button" className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">{client ? 'EDITAR CLIENTE' : 'NOVO CLIENTE'}</span><h2>{client ? 'Atualize o cliente' : 'Cadastre um cliente'}</h2><Field label="Razão social" name="legal_name" defaultValue={value('legal_name')} placeholder="Razão social" /><Field label="Nome fantasia" name="trade_name" defaultValue={value('trade_name')} placeholder="Nome fantasia" /><div className="form-grid"><Field label="CPF/CNPJ" name="document" defaultValue={value('document')} /><Field label="E-mail" name="email" type="email" defaultValue={value('email')} /></div><div className="form-grid"><Field label="Telefone" name="phone" defaultValue={value('phone')} /><Field label="Cidade" name="city" defaultValue={value('city')} /></div><label className="field"><span>Estado</span><select name="state" defaultValue={value('state') || 'GO'}>{BRAZIL_STATES.map((state) => <option key={state}>{state}</option>)}</select></label><label className="field"><span>Observações</span><textarea name="notes" defaultValue={value('notes')} /></label><div className="modal-actions"><button type="button" className="outline-button" onClick={onClose}>Cancelar</button><button className="blue-button">Salvar cliente</button></div></form></div> }
function SuppliersPage({ suppliers, pagination, onLoad, onSave, onArchive, notify, can }) { const [search, setSearch] = useState(''); const [city, setCity] = useState(''); const [category, setCategory] = useState(''); const [modal, setModal] = useState(null); const [viewing, setViewing] = useState(null); function filter(event) { event.preventDefault(); onLoad({ search, city, category, page: 1 }) } return <><SectionHeading kicker="SUPRIMENTOS" title="Fornecedores" description="Cadastre parceiros e acompanhe compras, cotações e pagamentos." action={can('suppliers', 'create') && <button className="blue-button" onClick={() => setModal({})}><Plus size={17} /> Novo fornecedor</button>} /><form className="filter-bar panel" onSubmit={filter}><label className="search-box"><Search size={15} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar fornecedor, CNPJ ou e-mail" /></label><input className="filter-input" value={city} onChange={(event) => setCity(event.target.value)} placeholder="Cidade" /><input className="filter-input" value={category} onChange={(event) => setCategory(event.target.value)} placeholder="Categoria" /><button className="outline-button">Filtrar</button></form><div className="page-panel panel"><PanelHeading title={`${pagination.total || suppliers.length} fornecedores`} subtitle="Dados persistidos por empresa" action={<button className="quiet-button" onClick={() => onLoad({ sort: 'legal_name', direction: 'asc' })}>Ordenar A-Z <ArrowRight size={14} /></button>} /><div className="table-scroll"><table><thead><tr><th>FORNECEDOR</th><th>CNPJ</th><th>CONTATO</th><th>CIDADE</th><th>CATEGORIA</th><th /></tr></thead><tbody>{suppliers.map((supplier) => <tr key={supplier.id}><td><div className="project-name"><span className="project-icon blue"><UsersRound size={15} /></span><span><b>{supplier.trade_name || supplier.legal_name}</b><small>{supplier.legal_name}</small></span></div></td><td>{supplier.document || 'Não informado'}</td><td><b>{supplier.contact_name || 'Sem contato'}</b><small>{supplier.email || supplier.phone || 'Sem canal'}</small></td><td>{supplier.city || '-'}{supplier.state ? ` / ${supplier.state}` : ''}</td><td><em className="status blue">{supplier.category || 'Geral'}</em></td><td><div className="row-actions"><button className="table-action" onClick={() => setViewing(supplier)}>Ver</button>{can('suppliers', 'edit') && <button className="table-action" onClick={() => setModal(supplier)}>Editar</button>}{can('suppliers', 'archive') && <button className="table-action danger" onClick={() => onArchive(supplier)}>Arquivar</button>}</div></td></tr>)}</tbody></table>{!suppliers.length && <div className="empty">Nenhum fornecedor encontrado. Cadastre o primeiro parceiro.</div>}</div><Pagination pagination={pagination} onPage={(page) => onLoad({ page })} /></div>{modal && <SupplierModal supplier={modal.id ? modal : null} onClose={() => setModal(null)} onSave={(data) => { onSave(data, modal.id); setModal(null) }} />}{viewing && <SupplierDetails supplier={viewing} onClose={() => setViewing(null)} notify={notify} />}</> }
function Pagination({ pagination, onPage }) { if (!pagination?.totalPages || pagination.totalPages <= 1) return null; return <div className="pagination"><span>Página {pagination.page} de {pagination.totalPages} · {pagination.total} registros</span><div><button className="outline-button" disabled={pagination.page <= 1} onClick={() => onPage(pagination.page - 1)}>Anterior</button><button className="outline-button" disabled={pagination.page >= pagination.totalPages} onClick={() => onPage(pagination.page + 1)}>Próxima</button></div></div> }
function SupplierModal({ supplier, onClose, onSave }) { const field = (name) => supplier?.[name] || ''; return <div className="modal-layer" onClick={onClose}><form className="modal-card supplier-modal" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); const data = Object.fromEntries(form.entries()); onSave(data) }} onClick={(event) => event.stopPropagation()}><button type="button" className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">{supplier ? 'EDITAR FORNECEDOR' : 'NOVO FORNECEDOR'}</span><h2>{supplier ? 'Atualize os dados do parceiro' : 'Cadastre um fornecedor'}</h2><p>Os dados ficam isolados na empresa atual e entram no histórico de compras.</p><div className="form-grid"><Field label="Razão social" name="legal_name" defaultValue={field('legal_name')} placeholder="Razão social" /><Field label="Nome fantasia" name="trade_name" defaultValue={field('trade_name')} placeholder="Nome fantasia" /></div><div className="form-grid"><Field label="CPF/CNPJ" name="document" defaultValue={field('document')} placeholder="00.000.000/0000-00" /><Field label="Inscrição estadual" name="state_registration" defaultValue={field('state_registration')} placeholder="Inscrição estadual" /></div><div className="form-grid"><Field label="E-mail" name="email" type="email" defaultValue={field('email')} placeholder="contato@empresa.com" /><Field label="Telefone" name="phone" defaultValue={field('phone')} placeholder="(00) 00000-0000" /></div><div className="form-grid"><Field label="CEP" name="zip_code" defaultValue={field('zip_code')} placeholder="00000-000" /><Field label="Cidade" name="city" defaultValue={field('city')} placeholder="Rio Verde" /></div><div className="form-grid"><Field label="Endereço" name="address" defaultValue={field('address')} placeholder="Rua / Avenida" /><Field label="Número" name="address_number" defaultValue={field('address_number')} placeholder="100" /></div><div className="form-grid"><Field label="Pessoa de contato" name="contact_name" defaultValue={field('contact_name')} placeholder="Nome do contato" /><Field label="Categoria" name="category" defaultValue={field('category')} placeholder="Material estrutural" /></div><div className="form-grid"><Field label="Condição de pagamento" name="payment_terms" defaultValue={field('payment_terms')} placeholder="28 dias" /><Field label="Chave PIX" name="pix_key" defaultValue={field('pix_key')} placeholder="CNPJ ou e-mail" /></div><div className="form-grid"><Field label="Banco" name="bank" defaultValue={field('bank')} placeholder="Banco" /><Field label="Agência" name="bank_branch" defaultValue={field('bank_branch')} placeholder="Agência" /></div><Field label="Conta" name="bank_account" defaultValue={field('bank_account')} placeholder="Conta corrente" /><label className="field"><span>Estado</span><select name="state" defaultValue={field('state') || 'GO'}>{BRAZIL_STATES.map((state) => <option key={state}>{state}</option>)}</select></label><label className="field"><span>Observações</span><textarea name="notes" defaultValue={field('notes')} placeholder="Informações adicionais" /></label><div className="modal-actions"><button type="button" className="outline-button" onClick={onClose}>Cancelar</button><button className="blue-button">Salvar fornecedor</button></div></form></div> }
function HistoryPanel({ recordId, module }) { const [state, setState] = useState({ loading: false, error: '', entries: [] }); async function load() { setState({ loading: true, error: '', entries: [] }); const session = JSON.parse(localStorage.getItem('nexora-session') || 'null'); try { const response = await fetch(`${API_URL}/audit-logs/by-entity/${recordId}?module=${encodeURIComponent(module)}`, { headers: { Authorization: `Bearer ${session?.token || ''}` } }); if (response.status === 403) return setState({ loading: false, error: 'Histórico não disponível para este perfil.', entries: [] }); if (!response.ok) throw new Error('histórico'); setState({ loading: false, error: '', entries: await response.json() }) } catch { setState({ loading: false, error: 'Não foi possível carregar o histórico.', entries: [] }) } } // eslint-disable-next-line react-hooks/set-state-in-effect, react-hooks/exhaustive-deps
  // oxlint-disable-next-line react-hooks/set-state-in-effect, react-hooks/exhaustive-deps
  useEffect(() => { load() }, [recordId, module]); if (state.loading) return <DataState message="CARREGANDO HISTÓRICO..." />; if (state.error) return <div className="empty">{state.error}</div>; if (!state.entries.length) return <div className="empty">Não há dados cadastrados.</div>; return <div className="history-list">{state.entries.map((entry) => <article className="history-entry" key={entry.id}><time>{new Date(entry.created_at).toLocaleString('pt-BR')}</time><strong>{entry.user_name || 'Usuário'}</strong><span>{entry.action} · {entry.module}</span>{(entry.new_value || entry.old_value) && <small>{entry.new_value || entry.old_value}</small>}</article>)}</div> }
function SupplierDetails({ supplier, onClose, notify }) { const [history, setHistory] = useState(false); return <div className="modal-layer" onClick={onClose}><div className="modal-card supplier-details" onClick={(event) => event.stopPropagation()}><button className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">FICHA DO FORNECEDOR</span><h2>{supplier.trade_name || supplier.legal_name}</h2><p>{supplier.legal_name} · {supplier.document || 'Documento não informado'}</p><div className="detail-tabs"><button className={!history ? 'selected' : ''} onClick={() => setHistory(false)}>Resumo</button><button onClick={() => notify('Histórico de compras pronto para conectar.')}>Compras</button><button onClick={() => notify('Cotações do fornecedor.')}>Cotações</button><button onClick={() => notify('Pagamentos do fornecedor.')}>Pagamentos</button><button onClick={() => notify('Contratos do fornecedor.')}>Contratos</button><button onClick={() => notify('Documentos do fornecedor.')}>Documentos</button><button className={history ? 'selected' : ''} onClick={() => setHistory(true)}>Histórico</button></div>{history ? <HistoryPanel recordId={supplier.id} module="SUPPLIERS" /> : <div className="supplier-summary"><div><small>Contato</small><b>{supplier.contact_name || 'Não informado'}</b></div><div><small>E-mail</small><b>{supplier.email || 'Não informado'}</b></div><div><small>Telefone</small><b>{supplier.phone || 'Não informado'}</b></div><div><small>Localização</small><b>{supplier.city || '-'} / {supplier.state || '-'}</b></div></div>}</div></div> }
function PurchasesPage({ requests, quotations, session, projects = [], onSelectQuotation, notify }) { const [checklistRequest, setChecklistRequest] = useState(null); const [checklistPickerOpen, setChecklistPickerOpen] = useState(false); const [compare, setCompare] = useState(null); const [search, setSearch] = useState(''); const filtered = requests.filter((request) => `${request.number || ''} ${request.justification || ''} ${request.status || ''}`.toLowerCase().includes(search.toLowerCase())); return <><SectionHeading kicker="SUPRIMENTOS" title="Compras" description="Solicitações de todas as obras, com checklist do material enviado para conferência na chegada." /><div className="purchase-flow"><span className="active">Solicitações das obras</span><ArrowRight size={15} /><span>Cotação</span><ArrowRight size={15} /><span className="active">Comparação</span><ArrowRight size={15} /><span>Aprovação</span><ArrowRight size={15} /><span>Ordem de compra</span><ArrowRight size={15} /><span>Checklist e conferência</span></div><div className="filter-bar panel"><label className="search-box"><Search size={15} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar solicitação" /></label><button className="outline-button" onClick={() => notify('Filtros de compras disponíveis.')}>Filtrar</button></div><div className="page-panel panel"><PanelHeading title={`${filtered.length} solicitações`} subtitle="Pedidos semanais recebidos de todas as obras" action={<div className="row-actions"><button className="outline-button" onClick={() => setChecklistPickerOpen(true)}><ClipboardList size={15} /> Criar checklist</button><button className="quiet-button" onClick={() => notify('Exportação disponível por endpoint protegido.')}>Exportar <ArrowRight size={14} /></button></div>} /><div className="table-scroll"><table><thead><tr><th>OBRA</th><th>NÚMERO</th><th>JUSTIFICATIVA</th><th>PRIORIDADE</th><th>NECESSÁRIA EM</th><th>STATUS</th><th /></tr></thead><tbody>{filtered.map((request) => { const requestQuotes = quotations.filter((quotation) => quotation.purchase_request_id === request.id); return <tr key={request.id}><td>{projects.find((project) => project.id === request.project_id)?.name || "Obra não informada"}</td><td><b>{request.number || request.id.slice(0, 8)}</b></td><td>{request.justification}</td><td>{request.priority || 'Normal'}</td><td>{request.needed_date || '-'}</td><td><em className={`status ${request.status === 'APROVADA' ? 'green' : 'blue'}`}>{request.status}</em></td><td>{requestQuotes.length > 0 && <button className="table-action" onClick={() => setCompare(request)}>Comparar {requestQuotes.length}</button>}<button className="table-action" onClick={() => setChecklistRequest(request)}>Checklist de envio</button></td></tr> })}</tbody></table>{!filtered.length && <div className="empty">Nenhuma solicitação encontrada.</div>}</div></div>{checklistPickerOpen && <ChecklistRequestPicker requests={requests} projects={projects} onClose={() => setChecklistPickerOpen(false)} onChoose={(request) => { setChecklistPickerOpen(false); setChecklistRequest(request) }} />} {checklistRequest && <PurchaseChecklistModal request={checklistRequest} session={session} notify={notify} onClose={() => setChecklistRequest(null)} />}{compare && <QuoteCompareModal request={compare} quotations={quotations.filter((quotation) => quotation.purchase_request_id === compare.id)} onClose={() => setCompare(null)} onSelect={(quotation) => { onSelectQuotation(quotation); setCompare(null) }} />}</> }
function ChecklistRequestPicker({ requests, projects, onClose, onChoose }) { const availableRequests = requests; return <div className="modal-layer" onClick={onClose}><div className="modal-card" onClick={(event) => event.stopPropagation()}><button className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">SETOR DE COMPRAS</span><h2>Criar checklist de envio</h2><p>Selecione a solicitação da obra e informe os itens e quantidades que serão enviados.</p>{availableRequests.length ? <div className="checklist-request-list">{availableRequests.map((request) => <button className="checklist-request-option" key={request.id} onClick={() => onChoose(request)}><span><b>{projects.find((project) => project.id === request.project_id)?.name || 'Obra não informada'}</b><small>{request.number || request.id.slice(0, 8)} · {request.justification}</small></span><ArrowRight size={16} /></button>)}</div> : <div className="empty">Nenhuma solicitação foi encontrada. As solicitações enviadas pelas obras aparecerão aqui.</div>}<div className="modal-actions"><button className="outline-button" onClick={onClose}>Fechar</button></div></div></div> }function PurchaseChecklistModal({ request, session, notify, onClose }) { const [items, setItems] = useState([]); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const headers = { Authorization: 'Bearer ' + session.token, 'Content-Type': 'application/json' }; useEffect(() => { let active = true; (async () => { try { const response = await fetch(API_URL + '/purchase-requests/' + request.id + '/checklist', { headers }); const saved = await response.json(); if (!response.ok) throw new Error(saved.error); if (saved.items && saved.items.length) { if (active) setItems(saved.items) } else { const itemResponse = await fetch(API_URL + '/purchase-requests/' + request.id + '/items', { headers }); const source = await itemResponse.json(); if (active) setItems(source.map((item) => ({ description: item.description, quantity: Number(item.quantity), received_quantity: 0 }))) } } catch (error) { notify(error.message || 'Não foi possível carregar o checklist.') } finally { if (active) setLoading(false) } })(); return () => { active = false } }, [request.id]); async function save() { setSaving(true); try { const response = await fetch(API_URL + '/purchase-requests/' + request.id + '/checklist', { method: 'PUT', headers, body: JSON.stringify({ items }) }); const result = await response.json(); if (!response.ok) throw new Error(result.error); setItems(result.items); notify('Checklist salvo para conferência na obra.') } catch (error) { notify(error.message || 'Não foi possível salvar o checklist.') } finally { setSaving(false) } } return <div className="modal-layer" onClick={onClose}><div className="modal-card" onClick={(event) => event.stopPropagation()}><button className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">CONFERÊNCIA DE MATERIAIS</span><h2>Checklist da obra</h2><p>Ajuste o que foi liberado pelo setor de compras. O almoxarife informa a quantidade conferida quando o material chegar.</p>{loading ? <div className="empty">Carregando itens…</div> : <div className="supply-lines">{items.map((item, index) => <div className="supply-line" key={index}><b>{item.description}</b><label className="field"><span>Quantidade enviada</span><input type="number" min="0.01" step="any" value={item.quantity} onChange={(event) => setItems((current) => current.map((row, i) => i === index ? { ...row, quantity: Number(event.target.value) } : row))} /></label><label className="field"><span>Conferida na obra</span><input type="number" min="0" max={item.quantity} step="any" value={item.received_quantity || 0} onChange={(event) => setItems((current) => current.map((row, i) => i === index ? { ...row, received_quantity: Number(event.target.value) } : row))} /></label></div>)}{!items.length && <div className="empty">Esta solicitação não possui itens para conferir.</div>}</div>}<div className="modal-actions"><button className="outline-button" onClick={onClose}>Fechar</button><button className="blue-button" disabled={loading || saving || !items.length} onClick={save}>{saving ? 'Salvando…' : 'Salvar checklist'}</button></div></div></div> }function QuoteCompareModal({ request, quotations, onClose, onSelect }) { return <div className="modal-layer" onClick={onClose}><div className="modal-card quote-modal" onClick={(event) => event.stopPropagation()}><button className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">COMPARAÇÃO DE COTAÇÕES</span><h2>{request.number || request.id.slice(0, 8)}</h2><p>{request.justification}</p><div className="quote-compare">{quotations.map((quotation) => <article className="quote-card" key={quotation.id}><strong>{quotation.supplier_name || quotation.supplier_id}</strong><span>Valor total <b>R$ {Number(quotation.total || 0).toLocaleString('pt-BR')}</b></span><span>Valor unitário <b>R$ {Number(quotation.unit_price || 0).toLocaleString('pt-BR')}</b></span><span>Frete <b>R$ {Number(quotation.freight || 0).toLocaleString('pt-BR')}</b></span><span>Entrega <b>{quotation.delivery_days || '-'} dias</b></span><span>Pagamento <b>{quotation.payment_terms || '-'}</b></span><span>Validade <b>{quotation.valid_until || '-'}</b></span><button className="blue-button" onClick={() => onSelect(quotation)} disabled={quotation.status === 'SELECIONADA'}>{quotation.status === 'SELECIONADA' ? 'Selecionada' : 'Selecionar fornecedor'}</button></article>)}</div></div></div> }
function PurchaseRequestModal({ projects = [], onClose, onCreate }) { const [items, setItems] = useState([{ description: '', quantity: '1', unit: 'UN' }]); return <div className="modal-layer" onClick={onClose}><form className="modal-card" onClick={(event) => event.stopPropagation()} onSubmit={(event) => { event.preventDefault(); const form = Object.fromEntries(new FormData(event.currentTarget)); onCreate({ ...form, items: items.filter((item) => item.description.trim()) }) }}><button type="button" className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">PEDIDO SEMANAL DA OBRA</span><h2>Nova solicitação</h2><p>Informe a obra, os materiais necessários e as quantidades.</p><div className="form-grid"><label className="field"><span>Obra</span><select name="project_id" required defaultValue=""><option value="" disabled>Selecione a obra</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select></label><label className="field"><span>Prioridade</span><select name="priority" defaultValue="NORMAL"><option>NORMAL</option><option>URGENTE</option><option>BAIXA</option></select></label></div><div className="form-grid"><Field label="Data necessária" name="needed_date" type="date" /><Field label="Centro de custo" name="cost_center" placeholder="Obras / Campo" /></div><Field label="Justificativa" name="justification" placeholder="Explique a necessidade da compra" required /><div className="supply-lines"><div className="supply-lines-heading"><strong>Materiais solicitados</strong><button type="button" className="quiet-button" onClick={() => setItems((current) => [...current, { description: '', quantity: '1', unit: 'UN' }])}><Plus size={14} /> Adicionar item</button></div>{items.map((item, index) => <div className="supply-line" key={index}><Field label="Material" value={item.description} onChange={(event) => setItems((current) => current.map((row, i) => i === index ? { ...row, description: event.target.value } : row))} required /><Field label="Quantidade" type="number" min="0.01" step="any" value={item.quantity} onChange={(event) => setItems((current) => current.map((row, i) => i === index ? { ...row, quantity: event.target.value } : row))} required /></div>)}</div><label className="field"><span>Observações</span><textarea name="observations" placeholder="Informações complementares" /></label><div className="modal-actions"><button type="button" className="outline-button" onClick={onClose}>Cancelar</button><button className="blue-button">Enviar solicitação</button></div></form></div> }function StockMovementModal({ supplies, projects, onClose, onSubmit }) { const [action, setAction] = useState('RETIRADA'); return <div className="modal-layer" onClick={onClose}><form className="modal-card" onClick={(event) => event.stopPropagation()} onSubmit={(event) => { event.preventDefault(); const form = Object.fromEntries(new FormData(event.currentTarget)); onSubmit({ ...form, action }) }}><button type="button" className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">MOVIMENTAÇÃO DE ESTOQUE</span><h2>Novo registro</h2><p>Registre a retirada de um item emprestado ou sua devolução ao almoxarifado.</p><label className="field"><span>Tipo de registro</span><select value={action} onChange={(event) => setAction(event.target.value)}><option value="RETIRADA">Empréstimo / retirada</option><option value="DEVOLUCAO">Devolução</option></select></label><label className="field"><span>Material</span><select name="product_id" required defaultValue=""><option value="" disabled>Selecione o material do estoque</option>{supplies.map((item) => <option key={item.id} value={item.id}>{item.name} · saldo {item.quantity}</option>)}</select></label><div className="form-grid"><label className="field"><span>Obra de destino (opcional)</span><select name="project_id" defaultValue=""><option value="">Estoque central</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.name}</option>)}</select></label><Field label="Quantidade" name="quantity" type="number" min="0.01" step="any" required /></div><Field label="Funcionário responsável" name="employee_name" placeholder="Nome do auxiliar ou funcionário" required /><Field label="Observação (opcional)" name="note" placeholder="Ex.: ferramenta emprestada para montagem" /><div className="modal-actions"><button type="button" className="outline-button" onClick={onClose}>Cancelar</button><button className="blue-button">{action === 'RETIRADA' ? 'Registrar empréstimo' : 'Registrar devolução'}</button></div></form></div> }function SupplyModal({ projects, onClose, onCreate }) { const [items, setItems] = useState([{ name: '', category: 'Ferramenta', amount: '1', tone: 'green', status: 'Em dia' }]); function updateItem(index, field, value) { setItems((current) => current.map((item, itemIndex) => itemIndex === index ? { ...item, [field]: value } : item)) } function addItem() { setItems((current) => [...current, { name: '', category: 'Ferramenta', amount: '1', tone: 'green', status: 'Em dia' }]) } return <div className="modal-layer" onClick={onClose}><form className="modal-card supply-modal" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); onCreate({ items: items.filter((item) => item.name), obra: form.get('obra'), purchaseDate: form.get('purchaseDate'), invoice: form.get('invoice')?.name }) }} onClick={(event) => event.stopPropagation()}><button type="button" className="modal-x" onClick={onClose}><X size={18} /></button><span className="section-kicker">ENTRADA DE COMPRA</span><h2>Novo insumo</h2><p>Registre vários itens da mesma compra com uma única nota fiscal.</p><div className="form-grid"><label className="field"><span>Obra de destino</span><select name="obra" required defaultValue=""><option value="" disabled>Selecione a obra</option>{projects.map((project) => <option key={project.code}>{project.name}</option>)}</select></label><Field label="Data da compra" name="purchaseDate" type="date" required /></div><label className="file-field"><span>Nota fiscal em PDF</span><input type="file" name="invoice" accept="application/pdf" required /><small>Uma nota pode conter todos os insumos desta compra.</small></label><div className="supply-lines"><div className="supply-lines-heading"><strong>Itens da compra</strong><button type="button" className="quiet-button" onClick={addItem}><Plus size={14} /> Adicionar item</button></div>{items.map((item, index) => <div className="supply-line" key={index}><label className="field"><span>Tipo do insumo</span><select required value={item.name} onChange={(event) => updateItem(index, 'name', event.target.value)}><option value="">Selecione</option>{['Lixadeira', 'Parafusadeira', 'Máquina de solda', 'Eletrodo', 'Chave de fenda', 'Fita isolante', 'Fita zebrada', 'Chapas galvanizadas', 'Parafusos', 'Sensor de temperatura', 'Outro'].map((name) => <option key={name}>{name}</option>)}</select></label><label className="field"><span>Categoria</span><select value={item.category} onChange={(event) => updateItem(index, 'category', event.target.value)}><option>Ferramenta</option><option>Material elétrico</option><option>Material estrutural</option><option>Consumível</option></select></label><Field label="Quantidade" name={`amount-${index}`} type="number" min="1" value={item.amount} onChange={(event) => updateItem(index, 'amount', event.target.value)} /></div>)}</div><div className="modal-actions"><button type="button" className="outline-button" onClick={onClose}>Cancelar</button><button className="blue-button">Adicionar ao estoque</button></div></form></div> }

function BusinessModulePage({ module, liveStats, session }) {
  const [budgets, setBudgets] = useState([])
  const [budgetLoading, setBudgetLoading] = useState(false)
  const [budgetError, setBudgetError] = useState('')
  const isBudgets = module === 'Orçamentos e propostas'
  const isReports = module === 'Relatórios'
  useEffect(() => {
    if (!isBudgets || !session?.token) return undefined
    let active = true
    setBudgetLoading(true); setBudgetError('')
    fetch(`${API_URL}/budgets?page=1&pageSize=100`, { headers: { Authorization: `Bearer ${session.token}` } })
      .then(async (response) => { const payload = await response.json(); if (!response.ok) throw new Error(payload.error || 'Não foi possível carregar os orçamentos.'); return rowsFrom(payload) })
      .then((rows) => { if (active) setBudgets(rows) })
      .catch((error) => { if (active) setBudgetError(error.message || 'Não foi possível carregar os orçamentos.') })
      .finally(() => { if (active) setBudgetLoading(false) })
    return () => { active = false }
  }, [isBudgets, session?.token])
  const descriptions = {
    'Leads e CRM': 'Acompanhe oportunidades comerciais e o relacionamento com seus clientes.',
    'Orçamentos e propostas': 'Consulte os orçamentos comerciais registrados para seus clientes e obras.',
    'Relatórios': 'Indicadores atuais da operação para acompanhar a gestão da empresa.',
  }
  return <>
    <SectionHeading kicker={isReports ? 'GESTÃO E ANÁLISE' : 'GESTÃO COMERCIAL'} title={module} description={descriptions[module] || 'Área de trabalho da empresa.'} />
    {isBudgets ? <section className="page-panel panel"><PanelHeading title={`${budgets.length} orçamentos`} subtitle="Registros cadastrados na empresa" />{budgetLoading ? <DataState message="Carregando orçamentos…" /> : budgetError ? <DataState message={budgetError} /> : budgets.length ? <div className="table-scroll"><table><thead><tr><th>NÚMERO</th><th>TOTAL</th><th>STATUS</th><th>CRIADO EM</th></tr></thead><tbody>{budgets.map((budget) => <tr key={budget.id}><td><b>{budget.number}</b></td><td>R$ {Number(budget.total || 0).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td><td><em className={`status ${budget.status === 'APROVADO' ? 'green' : 'blue'}`}>{budget.status || 'RASCUNHO'}</em></td><td>{budget.created_at ? new Date(budget.created_at).toLocaleDateString('pt-BR') : '—'}</td></tr>)}</tbody></table></div> : <DataState message="Ainda não há orçamentos cadastrados." />}</section>
      : isReports ? <><div className="metric-grid">{(liveStats?.stats || []).map((stat) => <Metric key={stat.label} icon={iconComponents[stat.icon] || BarChart3} label={stat.label} value={stat.value} detail={stat.detail} color={stat.tone || 'blue'} />)}</div><section className="page-panel panel"><PanelHeading title="Relatórios de gestão" subtitle="Resumo baseado nos dados disponíveis para sua empresa" />{liveStats?.stats?.length ? <div className="module-list">{liveStats.stats.map((stat) => <div className="module-row" key={stat.label}><div><b>{stat.label}</b><small>{stat.detail}</small></div><strong>{stat.value}</strong></div>)}</div> : <DataState message="Não há indicadores disponíveis para exibir." />}</section></>
        : <section className="page-panel panel"><PanelHeading title="Leads e oportunidades" subtitle="Relacionamento comercial" /><DataState message="A tela de Leads e CRM está disponível. Ainda não há registros comerciais cadastrados." /></section>}
  </>
}

function HelpPage() {
  const topics = [
    ['Projetos e obras', 'Cadastre as obras para relacionar equipes, solicitações de materiais e atividades de campo.'],
    ['Funcionários e segurança', 'Mantenha os cadastros da equipe, documentos, certificados e validades atualizados.'],
    ['Estoque e compras', 'Registre empréstimos e devoluções no Estoque. As solicitações das obras e checklists ficam em Compras.'],
    ['Documentos e contratos', 'Use as pastas para organizar arquivos da empresa e contratos em PDF.'],
  ]
  return <><SectionHeading kicker="SUPORTE" title="Central de ajuda" description="Orientações rápidas para as principais áreas do Nexora." /><div className="help-grid">{topics.map(([title, text]) => <article className="help-card" key={title}><CircleHelp size={21} /><h3>{title}</h3><p>{text}</p></article>)}</div></>
}

const SettingsPage = AdminPage
function AdministrationPage({ session, notify }) { return <AdminPage session={session} notify={notify} /> }

export { AdminPage, AdministrationPage, AppNew, AuthScreen, ClientsPage, HistoryPanel, Pagination, ProjectsPage, StockPage, SuppliersPage }
